// runtime/telemetry/emit_burst.go (excerpt)
if detector.CheckBurst(invocation) {
  metrics.Counter("invocation.burst_count").Inc()
  metrics.Gauge("invocation.burst_member_count").Set(float64(detector.MemberCount()))
  span.SetTag("invocation_phase", detector.DominantPhase())
  // emit exemplar linking span -> burst id
  metrics.Histogram("burst_duration_seconds").ObserveWithExemplar(dur.Seconds(), map[string]string{"burst_id": detector.ID()})
}

// services/observability/throttler/main.go (excerpt)
func decide(req DecisionRequest) DecisionOutcome {
  if recentBursts.Matches(req.fingerprint) && req.phase == "stream" {
    return HOLD
  }
  // default escalate if p99 latency > threshold
  if req.p99 > cfg.EscalationP99 {
    return ESCALATE
  }
  return HOLD
}
